      {
        "type": "paragraph",
        "snippet": "You can change or correct your name on your voter ID card online by submitting Form 8 through the Election Commission of India Portal or the Voter Helpline mobile app.",
        "snippet_links": [
          {
            "text": "Election Commission of India Portal",
            "link": "https://voters.eci.gov.in/"
          }
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "heading",
        "snippet": "Steps to Change Name Online"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Register or Log In: Go to the Election Commission of India Portal. Click on Sign-Up to create an account with your mobile number and email ID if you are a new user, or click Login if you already have one.",
            "reference_indexes": [
              1,
              2
            ]
          },
          {
            "snippet": "Select Form 8: From the dashboard or services section, select Form 8 (Application for shifting of residence, correction of entries, replacement of EPIC, or marking as PwD).",
            "reference_indexes": [
              3,
              4
            ]
          },
          {
            "snippet": "Choose \"Self\" or \"Other\": Select whether you are submitting the form for yourself or another registered elector, and enter your EPIC (Elector Photo Identity Card) number.",
            "reference_indexes": [
              5
            ]
          },
          {
            "snippet": "Select Correction Type: Choose the option for Correction of entries in existing electoral roll.",
            "reference_indexes": [
              6
            ]
          },
          {
            "snippet": "Enter New Name: Select Name as the detail to be corrected and type in your updated or corrected name.",
            "reference_indexes": [
              3,
              5
            ]
          },
          {
            "snippet": "Upload Supporting Documents: Attach a scanned copy of a valid document showing your new name (such as an Aadhaar card, PAN card, marriage certificate, or official gazette notification).",
            "reference_indexes": [
              5,
              7
            ]
          },
          {
            "snippet": "Submit the Form: Fill out the declaration, enter the captcha code, and submit the application. You will receive a reference number to track your application status online.",
            "reference_indexes": [
              8,
              9
            ]
          }
        ]
      }
    ],
